using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfig;
    private static IList<ScenarioDefinition>? s_scenarios;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_scenarios = ScenarioLoader.Load("evaluation.yml");

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator(),
        };

        s_reportingConfig = new ReportingConfiguration(
            evaluators,
            chatClientForEvaluation: CreateJudgeChatClient(),
            reportStorageRootPath: Path.Combine(context.TestRunResultsDirectory!, "evaluation-reports"));
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(string scenarioName)
    {
        var scenario = s_scenarios!.First(s => s.Name == scenarioName);

        await using var session = await s_reportingConfig!.CreateScenarioRunAsync(scenarioName);

        var chatClient = CreateChatClient();
        var messages = new List<ChatMessage>();
        ChatResponse? response = null;

        foreach (var turn in scenario.Turns)
        {
            messages.Add(new ChatMessage(ChatRole.User, turn.Content));
            response = await chatClient.GetResponseAsync(messages);
            messages.AddRange(response.Messages);
        }

        Assert.IsNotNull(response);

        await session.EvaluateAsync(messages, response);

        foreach (var expectation in scenario.Expectations)
        {
            var result = session.GetNumericMetricResult(expectation.Metric);
            Assert.IsTrue(
                result.Value >= expectation.Threshold,
                $"Metric '{expectation.Metric}' scored {result.Value}, expected >= {expectation.Threshold}");
        }
    }

    private static IEnumerable<object[]> GetScenarios()
    {
        var scenarios = ScenarioLoader.Load("evaluation.yml");
        return scenarios.Select(s => new object[] { s.Name });
    }

    private static IChatClient CreateChatClient()
    {
        // Uses the same model configured in the AppHost for agent-under-test
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT environment variable.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY environment variable.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }

    private static IChatClient CreateJudgeChatClient()
    {
        // Uses a stronger model as the LLM judge for evaluation metrics
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT environment variable.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY environment variable.");

        var modelName = Environment.GetEnvironmentVariable("AZURE_OPENAI_JUDGE_MODEL") ?? "gpt-4o";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(modelName)
            .AsIChatClient();
    }
}

using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

public static class ScenarioLoader
{
    public static IList<ScenarioDefinition> Load(string path)
    {
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .Build();

        var root = deserializer.Deserialize<ScenarioFile>(yaml);
        return root.Scenarios;
    }
}

public class ScenarioFile
{
    public List<ScenarioDefinition> Scenarios { get; set; } = new();
}

